$ErrorActionPreference = "Stop"

$root = (Get-Location).Path
$ws = Join-Path $root "runtime\workspaces\ahos-autopilot"
$pkg = Join-Path $ws "ahos_core"
$python = Join-Path $root ".venv\Scripts\python.exe"
$structurePath = Join-Path $pkg "ahos\department_structure.py"
$testPath = Join-Path $pkg "tests\test_department_structure.py"
$patcher = Join-Path $env:TEMP "ahos-039-patch.py"

Write-Host "=== AHOS-039 HOLDING DEPARTMENT EXPANSION ==="
Write-Host "LOCAL ONLY - OpenAI API calls: 0 - Paid API spend: USD 0"
Write-Host ""

if (-not (Test-Path $python)) { throw "Python venv not found." }
if (-not (Test-Path $pkg)) { throw "AHOS package not found." }

[IO.File]::WriteAllBytes(
    $structurePath,
    [Convert]::FromBase64String("")
)
[IO.File]::WriteAllBytes(
    $testPath,
    [Convert]::FromBase64String("")
)

$patchText = [Text.Encoding]::UTF8.GetString(
    [Convert]::FromBase64String("")
)
$patchText = $patchText.Replace("__PKG__", $pkg.Replace("\","\\"))
[IO.File]::WriteAllText(
    $patcher,
    $patchText,
    (New-Object System.Text.UTF8Encoding($false))
)

& $python $patcher
if ($LASTEXITCODE -ne 0) { throw "AHOS-039 patch failed." }

$old = $env:PYTHONPATH
Push-Location $pkg
try {
    $env:PYTHONPATH = $pkg

    Write-Host "Running department/workforce tests..."
    & $python -m pytest tests\test_department_structure.py tests\test_virtual_workforce.py -q
    if ($LASTEXITCODE -ne 0) {
        throw "AHOS-039 department/workforce tests failed."
    }

    Write-Host "Running full AHOS test suite..."
    & $python -m pytest -q
    if ($LASTEXITCODE -ne 0) {
        throw "Full AHOS tests failed."
    }

    Write-Host "Verifying department structure..."
    & $python -c "from ahos.virtual_workforce import default_virtual_workforce; from ahos.department_structure import build_department_structure; w=default_virtual_workforce(); s=build_department_structure(w); print('WORKERS:',len(w)); print('DEPARTMENTS:',len(s)); [print(x.department,'->',x.manager_id,'->',','.join(x.worker_ids)) for x in s]"
    if ($LASTEXITCODE -ne 0) {
        throw "Department structure verification failed."
    }
}
finally {
    Pop-Location
    $env:PYTHONPATH = $old
    Remove-Item $patcher -Force -ErrorAction SilentlyContinue
}

git -C $ws add `
    ahos_core/ahos/virtual_workforce.py `
    ahos_core/ahos/department_structure.py `
    ahos_core/tests/test_department_structure.py `
    ahos_core/AHOS_BACKLOG.json

$staged = git -C $ws diff --cached --name-only
if ($staged) {
    git -C $ws -c user.name="Miniverse Autopilot" -c user.email="miniverse@local.invalid" `
        commit -m "feat(ahos): expand holding department managers"
    if ($LASTEXITCODE -ne 0) { throw "git commit failed." }

    git -C $ws push origin HEAD
    if ($LASTEXITCODE -ne 0) { throw "git push failed." }
} else {
    Write-Host "Git: no staged changes; AHOS-039 already present."
}

Write-Host ""
Write-Host "=== AHOS-039 COMPLETE ==="
Write-Host "Core departments: 11"
Write-Host "Department managers: 11"
Write-Host "Specialist workers retained: PASS"
Write-Host "Department hierarchy validation: PASS"
Write-Host "Specialist routing stability: PASS"
Write-Host "Paid AI default: OFF"
Write-Host "Full AHOS tests: PASS"
Write-Host "OpenAI API calls: 0"
Write-Host "Paid API spend: USD 0"
Write-Host ""
Write-Host "CORE ROADMAP REMAINING: AHOS-040 through AHOS-042."
Write-Host "NEXT: AHOS-040 converts qualified opportunities into queued missions."
